module Top;
    class Resource; endclass
    class Box #(type T = int) extends Resource; endclass
    typedef bit [3:0] nibble_t;
    initial begin
        Box#(bit [3:0]) made = new;
        Resource r = made;
        Box#(nibble_t) a;
        begin
            typedef bit [3:0] t;
            Box#(t) b;
            $display("[%0d %0d %0d]", $cast(a, r), $cast(b, r), $cast(made, r));
        end
    end
endmodule
